#include "unity.h"
#include "ride_events.h"

void setUp(void)
{
}

void tearDown(void)
{
}

static void set_active_events(ride_events_t *state,
                              bool speeding,
                              bool wide_turn,
                              bool speedbreaker,
                              bool sudden_braking)
{
    state->active[RIDE_SPEEDING] = speeding;
    state->active[RIDE_TURN] = wide_turn;
    state->active[RIDE_BUMP] = speedbreaker;
    state->active[RIDE_BRAKING] = sudden_braking;
}

void test_FR_015_01(void)
{
    ride_events_t state;
    ride_event_t selected;

    ride_events_init(&state, false);
    set_active_events(&state, true, true, true, true);
    selected = ride_events_update(&state, 0U, NULL);
    TEST_ASSERT_EQUAL_INT(RIDE_BRAKING, selected);
    TEST_ASSERT_EQUAL_STRING("Sudden Braking", ride_events_message(selected));

    ride_events_init(&state, false);
    set_active_events(&state, true, true, true, false);
    selected = ride_events_update(&state, 0U, NULL);
    TEST_ASSERT_EQUAL_INT(RIDE_BUMP, selected);
    TEST_ASSERT_EQUAL_STRING("Unseen SpeedBreaker", ride_events_message(selected));

    ride_events_init(&state, false);
    set_active_events(&state, true, true, false, false);
    selected = ride_events_update(&state, 0U, NULL);
    TEST_ASSERT_EQUAL_INT(RIDE_TURN, selected);
    TEST_ASSERT_EQUAL_STRING("Wide Turn", ride_events_message(selected));
}
